/**
 * Captured stage frames for the two use-case process decks (owner:
 * PageFamilies; consumed by pages/behaviours.tsx).
 *
 * Source: https://www.tano.ai/use-cases/{drive-revenue,creative-velocity}
 * rendered in Chromium at 1568x709, 2026-11-27. For every segment button
 * the live deck was selected and the resulting `.hp-pp-frame` outerHTML
 * captured. Each payload is gzip + base64 of that sanitized frame. Image
 * URLs were rewritten to local /sites/tano/images assets before
 * compression; all other markup (scene classes, `--at`/`--room`
 * animation inputs, SVG defs) is verbatim so src/styles/design-system.css
 * drives the scene exactly as it does on the live site.
 *
 * Order matches the .hp-steps-seg-button order.
 */

export const DRIVE_SCENE_FRAMES_GZ: readonly string[] = [
  "",
  "",
  "",
  "",
];

export const CREATIVE_SCENE_FRAMES_GZ: readonly string[] = [
  "",
  "",
  "",
  "",
  "",
];

/** Decode a captured `.hp-pp-frame` payload. */
export async function loadUseCaseScenes(
  key: "drive-revenue" | "creative-velocity",
): Promise<string[]> {
  const payloads = key === "creative-velocity" ? CREATIVE_SCENE_FRAMES_GZ : DRIVE_SCENE_FRAMES_GZ;
  return Promise.all(
    payloads.map(async (payload) => {
      const bytes = Uint8Array.from(atob(payload), (c) => c.charCodeAt(0));
      const stream = new Blob([bytes]).stream().pipeThrough(new DecompressionStream("gzip"));
      return new Response(stream).text();
    }),
  );
}
